<?php
declare(strict_types=1);require_once __DIR__.'/../api/pesapal_status.php';
$config=require __DIR__.'/../config/config.php';$tracking=trim((string)($_GET['OrderTrackingId']??''));$ref=trim((string)($_GET['OrderMerchantReference']??''));$status='PENDING';$details=[];
if($tracking){try{$details=getStatus($tracking,$config);$status=strtoupper((string)($details['payment_status_description']??'PENDING'));$pdo=new PDO('sqlite:'.__DIR__.'/../data/donations.sqlite');$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$s=$pdo->prepare('UPDATE donations SET status=?,tracking_id=?,updated_at=? WHERE merchant_reference=? OR tracking_id=?');$s->execute([$status,$tracking,date('c'),$ref,$tracking]);}catch(Throwable $e){$status='PENDING';}}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$headline=$status==='COMPLETED'?'Donation Received — Thank You':($status==='FAILED'?'Payment Was Not Completed':'Donation Being Verified');$copy=$status==='COMPLETED'?'Your donation was confirmed by the payment provider. Thank you for supporting SIDAI CBO.':($status==='FAILED'?'The payment was not completed. You may return and try again.':'Your payment has returned to SIDAI CBO and is being verified. Please keep your payment reference.');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo h($headline); ?> | SIDAI CBO</title><link rel="stylesheet" href="../assets/css/donation.css"></head><body><main class="success"><div class="icon"><?php echo $status==='COMPLETED'?'✓':'♥'; ?></div><h1><?php echo h($headline); ?></h1><p><?php echo h($copy); ?></p><?php if($tracking): ?><p><strong>Payment reference:</strong> <?php echo h($tracking); ?></p><?php endif; ?><a class="donate-btn" style="display:inline-block;text-decoration:none;margin-top:15px" href="../index.php">Return to Donation Page</a></main></body></html>
